rest = []
for it in items():
    k = known(it[0])
    if k and k[0] == "200":
        tasks.append(it)
    elif not k:
        rest.append(it)
tasks += rest
print("задач: %d известных 200 + %d без HEAD, инструментов %d" % (len(tasks) - len(rest), len(rest), len(inst)), flush=True)

