stop = False
logf = open(os.path.join(outd, "_progress.log"), "a", buffering=1)
missf = open(os.path.join(outd, "_missing.tsv"), "a", buffering=1)
failf = open(os.path.join(outd, "_fails.tsv"), "a", buffering=1)
ctx = ssl.create_default_context()


